    `})},se={name:"Notice — Accepted",render:()=>({components:{DocumentViewerShell:ae},setup(){return{DOCUMENT:te,RECIPIENTS:de,notice:{variant:"success",text:"This contract has been signed and accepted by all parties."}}},template:`
      <DocumentViewerShell
